import { bytes, duration } from "./utils/format.js";
import Events from "./events.js";
import { rss } from "./services/process.js";
/**
 * DebugBar is a class that manages collections of items to be displayed in a debug bar.
 */
export default class DebugBar {
    #events = new Events();
    #measureItem;
    #ram = 0;
    collections = [];
    actions = [];
    /**
     * Clear all collections and actions
     */
    clear() {
        this.collections.forEach((collection) => (collection.items = []));
        this.actions = [];
        this.#measureItem = undefined;
    }
    /**
     * Get a collection by name or create a new one if it doesn't exist
     */
    collection(name) {
        const collection = this.collections.find((c) => c.name === name);
        if (collection) {
            return collection;
        }
        const newCollection = name === "Build"
            ? buildCollection()
            : {
                name,
                items: [],
            };
        this.collections.push(newCollection);
        return newCollection;
    }
    /**
     * Add a new a new action
     */
    action(action) {
        this.actions.push(action);
    }
    /**
     * Add a new item to the "Build" collection and return it
     */
    buildItem(title = "Untitled", context = "info") {
        const collection = this.collection("Build");
        const item = {
            title,
            context,
        };
        collection.items.push(item);
        return item;
    }
    dispatchEvent(event) {
        return this.#events.dispatchEvent(event);
    }
    addEventListener(type, listenerFn, options) {
        this.#events.addEventListener(type, listenerFn, options);
        return this;
    }
    /** Start a measure */
    startMeasure(name) {
        performance.mark(name);
    }
    /** End a measure and add it to the "Build" collection */
    endMeasure(name, title) {
        this.#measureItem ??= this.buildItem("Performance info", "info");
        this.#measureItem.items ??= [];
        performance.mark(`${name}-end`);
        const time = name === null ? performance.now() : performance.measure(name, name, `${name}-end`).duration;
        let item;
        const [ram, diff] = this.#getRam();
        if (name === "build") {
            item = this.#measureItem;
            item.title = title;
            item.icon = "clock";
            item.details = `${duration(time)} / ${bytes(ram)}`;
        }
        else if (time >= 1) {
            item = {
                title: title,
                details: `${duration(time)} / ${bytes(diff)}`,
            };
            this.#measureItem.items.push(item);
        }
        if (name) {
            performance.clearMarks(name);
            performance.clearMarks(`${name}-end`);
            performance.clearMeasures(name);
        }
        return item;
    }
    #getRam() {
        const ram = rss();
        const diff = ram - this.#ram;
        this.#ram = ram;
        return [ram, diff];
    }
}
/** Build collection created automatically by Lume */
function buildCollection() {
    const collection = {
        name: "Build",
        icon: "fire",
        empty: "No build messages found",
        contexts: {
            fatal: {
                background: "important",
            },
            error: {
                background: "error",
            },
            warn: {
                background: "warning",
            },
            info: {
                background: "info",
            },
            "lume cms": {
                background: "lightgreen",
            },
        },
        items: [],
    };
    return collection;
}
